class Goblin {
  constructor(public stats: Stats, public mesh: Mesh) {}

  // Deep-copy anything mutable so clones are truly independent
  clone(): Goblin {
    return new Goblin({ ...this.stats }, this.mesh);
  }
}

const prototypeGoblin = new Goblin(loadStats(), loadMesh("goblin"));

// Every spawn is a cheap in-memory copy
for (let i = 0; i < 1000; i++) {
  spawnGoblin(prototypeGoblin.clone());
}
